+import { sortChronologically } from "./agenda.js";
+import { summarizeAttendance } from "./attendance.js";
+
+function signupsFor(signupsByEvent, id) {
+  return signupsByEvent && Object.hasOwn(signupsByEvent, id) ? signupsByEvent[id] : [];
+}
+
+export function buildOrganizerDigest(events, signupsByEvent = {}) {
+  return sortChronologically(events).map(({ event, card }) => ({
+    ...card,
+    ...summarizeAttendance(event, signupsFor(signupsByEvent, card.id)),
+  }));
+}

